import { jsString } from '../util/safe.js';

// The framework owns request/response handling. Shared hashing, storage and session
// behavior are generated by session-auth.js from the same validated contract.
export const expressSessionReader = `
export function requestSessionId(req) {
  const header = req.headers.cookie;
  if (typeof header !== 'string') return null;
  for (const cookie of header.split(';')) {
    const index = cookie.indexOf('=');
    if (index < 0 || cookie.slice(0, index).trim() !== COOKIE_NAME) continue;
    try { return decodeURIComponent(cookie.slice(index + 1).trim()); }
    catch { return null; }
  }
  return null;
}
`;

export function expressGuard(safe) {
  return `import { requestSessionId, getSession } from './sessions.js';
import { users } from './store-adapter.js';

// Express middleware terminates unauthenticated requests before the route handler.
export function ${safe.guardName}(req, res, next) {
  const sessionId = requestSessionId(req);
  const session = sessionId ? getSession(sessionId) : null;
  if (!session) return res.status(${safe.unauthenticatedStatus}).json({ error: 'unauthenticated' });
  const user = users.byId(session.userId);
  if (!user) return res.status(${safe.unauthenticatedStatus}).json({ error: 'unauthenticated' });
  req.session = session;
  req.user = user;
  return next();
}
`;
}

export function expressRoutes(safe, endpoint) {
  const parts = [
    `import crypto from 'node:crypto';`,
    `import express from 'express';`,
    `import { hashPassword, verifyPassword } from './passwords.js';`,
    `import { createSession, destroySession, sessionCookie, clearedCookie, requestSessionId } from './sessions.js';`,
    `import { users } from './store-adapter.js';`,
    `import { ${safe.guardName} } from './guard.js';`,
    '',
    `const parseJsonBody = express.json();`,
    `function publicUser(user) { return { id: user.id, email: user.email, createdAt: user.createdAt }; }`,
    `function normaliseEmail(email) { return String(email ?? '').trim().toLowerCase(); }`,
    '',
    `export function registerAuthRoutes(app) {`,
  ];
  if (endpoint('register')) parts.push(`  app.post(${jsString(endpoint('register').path, 'endpoints.register.path')}, parseJsonBody, (req, res) => {
    const email = normaliseEmail(req.body?.email);
    const password = req.body?.password;
    if (!email || !password) return res.status(400).json({ error: 'email_and_password_required' });
    if (String(password).length < ${safe.minLength}) return res.status(400).json({ error: 'password_too_short' });
    if (users.byEmail(email)) return res.status(409).json({ error: 'email_already_registered' });
    const { salt, passwordHash } = hashPassword(String(password));
    const user = { id: crypto.randomUUID(), email, salt, passwordHash, createdAt: new Date().toISOString() };
    users.insert(user);
    const sessionId = createSession(user.id);
    return res.set('set-cookie', sessionCookie(sessionId)).status(201).json({ user: publicUser(user) });
  });
`);
  if (endpoint('login')) parts.push(`  app.post(${jsString(endpoint('login').path, 'endpoints.login.path')}, parseJsonBody, (req, res) => {
    const email = normaliseEmail(req.body?.email);
    const user = users.byEmail(email);
    // Unknown email and wrong password preserve the same response contract.
    if (!user || !verifyPassword(String(req.body?.password ?? ''), user.salt, user.passwordHash)) {
      return res.status(401).json({ error: 'invalid_credentials' });
    }
    const sessionId = createSession(user.id);
    return res.set('set-cookie', sessionCookie(sessionId)).status(200).json({ user: publicUser(user) });
  });
`);
  if (endpoint('logout')) parts.push(`  app.post(${jsString(endpoint('logout').path, 'endpoints.logout.path')}, (req, res) => {
    const sessionId = requestSessionId(req);
    if (sessionId) destroySession(sessionId);
    return res.set('set-cookie', clearedCookie()).status(200).json({ ok: true });
  });
`);
  if (endpoint('currentUser')) parts.push(`  app.get(${jsString(endpoint('currentUser').path, 'endpoints.currentUser.path')}, ${safe.guardName}, (req, res) => {
    return res.status(200).json({ user: publicUser(req.user) });
  });
`);
  parts.push('}');
  return parts.join('\n') + '\n';
}
